 import { MeshBasicNodeMaterial, PlaneGeometry, DoubleSide, SRGBColorSpace } from 'three/webgpu';
import { uv, vec3, mix, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new ctx.THREE.Group();
  group.name = config.id ?? 'quote-panel';

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const width = 2.4;
  const height = width * (320 / 512);

  // --- gradient backdrop stage plane ---
  const stageGeo = new PlaneGeometry(7, 6);
  const ink3 = new ctx.THREE.Color(colors.ink);
  const surface3 = new ctx.THREE.Color(colors.surface);
  const gradFactor = smoothstep(0.0, 1.0, uv().y);
  const bgNode = mix(
    vec3(surface3.r, surface3.g, surface3.b),
    vec3(ink3.r, ink3.g, ink3.b),
    gradFactor
  );
  const stageMat = new MeshBasicNodeMaterial({
    colorNode: bgNode,
    side: DoubleSide
  });
  const stage = new ctx.THREE.Mesh(stageGeo, stageMat);
  stage.position.z = -2.5;
  group.add(stage);

  // --- accent edge frame ---
  const edgeGeo = new PlaneGeometry(width * 1.05, height * 1.05);
  const edgeMat = new MeshBasicNodeMaterial({
    color: colors.accent,
    transparent: true,
    opacity: 0.85,
    side: DoubleSide
  });
  const edgeFrame = new ctx.THREE.Mesh(edgeGeo, edgeMat);
  edgeFrame.position.z = -0.02;
  edgeFrame.visible = false;
  group.add(edgeFrame);

  // --- textured card plane ---
  const cardGeo = new PlaneGeometry(width, height);
  const placeholderMat = new MeshBasicNodeMaterial({
    color: colors.surface,
    side: DoubleSide
  });
  const card = new ctx.THREE.Mesh(cardGeo, placeholderMat);
  group.add(card);

  // --- texture load ---
  let cardTexture = null;
  let disposed = false;

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      if (disposed) {
        tex.dispose();
        return;
      }
      cardTexture = tex;
      tex.colorSpace = SRGBColorSpace;

      // atlas region from config source rect (already 0,0,512,320)
      const atlas = config.atlasRegion ?? { x: 0, y: 0, w: 512, h: 320 };
      const imgW = tex.image?.width ?? atlas.w;
      const imgH = tex.image?.height ?? atlas.h;
      tex.offset.set(atlas.x / imgW, 1 - (atlas.y + atlas.h) / imgH);
      tex.repeat.set(atlas.w / imgW, atlas.h / imgH);
      tex.needsUpdate = true;

      const cardMat = new MeshBasicNodeMaterial({
        map: tex,
        side: DoubleSide
      });
      card.material.dispose();
      card.material = cardMat;
    });
  }

  // --- cinematic primitive: parallax-scroll ---
  const primResults = [];
  const primitiveList = config.cinematicPrimitives ?? [];
  for (const p of primitiveList) {
    if (p.name && ctx.primitives && typeof ctx.primitives[p.name] === 'function') {
      const res = ctx.primitives[p.name](group, p.params ?? {});
      primResults.push(res);
    }
  }

  // --- interaction handlers ---
  function hoverIn() {
    gsap.killTweensOf(card.position);
    gsap.to(card.position, {
      y: 0.15,
      duration: 0.35,
      ease: 'power2.out',
      overwrite: 'auto'
    });
  }

  function hoverOut() {
    gsap.killTweensOf(card.position);
    gsap.to(card.position, {
      y: 0,
      duration: 0.35,
      ease: 'power2.out',
      overwrite: 'auto'
    });
  }

  function onClick() {
    gsap.killTweensOf(card.scale);
    gsap.to(card.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out(1.7)',
      yoyo: true,
      repeat: 1,
      overwrite: 'auto'
    });
    ctx.emit('hub-pricing.select', { source: config.id });
  }

  function setFocus(active) {
    edgeFrame.visible = !!active;
  }

  group.userData.handlers = {
    hover: (active) => (active ? hoverIn() : hoverOut()),
    pointerenter: hoverIn,
    pointerleave: hoverOut,
    click: onClick,
    focus: setFocus
  };

  group.userData.dataBindings = (config.dataBindings ?? []).slice();

  group.userData.cleanup = () => {
    disposed = true;
    gsap.killTweensOf(card.position);
    gsap.killTweensOf(card.scale);
    gsap.killTweensOf(group.position);
    gsap.killTweensOf(group.scale);

    for (const res of primResults) {
      if (res && typeof res.cleanup === 'function') res.cleanup();
      if (res && res.timeline) res.timeline.kill?.();
    }

    cardGeo.dispose();
    stageGeo.dispose();
    edgeGeo.dispose();
    card.material?.dispose?.();
    stageMat.dispose();
    edgeMat.dispose();
    if (cardTexture) cardTexture.dispose();
  };

  return group;
}
